import os, re, json, glob, zipfile
from html import unescape

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9"

def load(path):
    text = open(path, encoding="utf-8", errors="replace").read()
    if path.endswith((".xml", ".html", ".htm")) or "&amp;" in text or "&#x27;" in text:
        text = unescape(text)
    return text

def g(t, pattern, flags=re.I|re.S):
    m = re.search(pattern, t, flags)
    if not m:
        return ""
    for grp in m.groups():
        if grp:
            return " ".join(grp.split())
    return ""

records = []
for path in sorted(glob.glob(ROOT + "/**/*", recursive=True)):
    if not os.path.isfile(path) or path.endswith(".xlsx"):
        continue
    rel = os.path.relpath(path, ROOT)
    t = load(path)
    rec = {
        "file": rel,
        "record": g(t, r"(CB-DOC-\d{3}-\d{3})"),
        "role": g(t, r'EVIDENCE ROLE:\s*([a-z_]+)') or g(t, r'Evidence role\s*\|\s*([a-z_]+)') or g(t, r'"evidence_role"\s*:\s*"([^"]+)"'),
        "issue": g(t, r"This record concerns\s+(.+?)\s+within\s+Project Daybreak"),
        "title": g(t, r"legal name Helios Forge, Inc\. — (.+?) record \d+"),
        "pk": g(t, r"PORTFOLIO KEY:\s*(CBP-[\d-]+)") or g(t, r"Portfolio key\s*\|?\s*(CBP-[\d-]+)"),
        "entities": sorted(set(re.findall(r"ENT-\d+-\d+", t))),
        "operative": [" ".join(s.split()) for s in re.findall(r"([^.]*CB-MA-2401-[A-Z]\d+[^.]*\.)", t)],
    }
    records.append(rec)

# fix role from md table pipes variant
for rec in records:
    if not rec["role"]:
        t = load(os.path.join(ROOT, rec["file"]))
        m = re.search(r"evidence[_ ]role[\"']?\s*[:|=]\s*[\"']?([a-z_]+)", t, re.I)
        if m: rec["role"] = m.group(1)

from collections import defaultdict
by_key = defaultdict(list)
for r in records:
    key = (r["issue"] or r["title"] or "?").strip()
    by_key[key].append(r)

print(f"{len(records)} files, {len(by_key)} distinct issues\n")
for k in sorted(by_key):
    v = by_key[k]
