import os, re, glob, zipfile
from html import unescape

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9"

def load(path):
    text = open(path, encoding="utf-8", errors="replace").read()
    return unescape(text)

# Group files by issue using the business-context issue phrase
issues = {
 "charter authorization mismatch": "01 Charter authorization mismatch",
 "financial covenant breach": "02 Financial covenant breach",
 "permit transfer restriction": "03 Permit transfer restriction",
 "revenue recognition exception": "04 Revenue recognition exception",
 "most-favored-customer exposure": "05 Most-favored-customer exposure",
 "unreported security incident": "06 Unreported security incident",
 "claims-made insurance tail": "07 Claims-made insurance tail",
 "anti-assignment restriction": "08 Anti-assignment restriction",
 "open-source copyleft exposure": "09 Open-source copyleft exposure",
 "sales-tax nexus gap": "10 Sales-tax nexus gap",
 "change-of-control consent": "11 Change-of-control consent",
 "invention assignment defect": "12 Invention assignment defect",
}

groups = {}
for path in sorted(glob.glob(ROOT + "/**/*", recursive=True)):
    if not os.path.isfile(path) or path.endswith(".xlsx"):
        continue
    rel = os.path.relpath(path, ROOT)
    t = load(path)
    hit = None
    for k in issues:
        if f"concerns {k} within" in t or f"— {k.title()} record" in t or f"— {k.capitalize()} record" in t or k.title() in t or k.capitalize() in t:
            hit = k
            break
    if hit is None:
        hit = "UNMATCHED:" + rel
    groups.setdefault(hit, []).append((rel, t))

def section(t, start_pat, end_pats):
    m = re.search(start_pat, t, re.I)
    if not m:
        return ""
    s = m.end()
    e = len(t)
    for p in end_pats:
        m2 = re.search(p, t[s:], re.I)
        if m2:
            e = min(e, s + m2.start())
    return " ".join(t[s:e].split())

out = []
for issue, label in issues.items():
    files = groups.get(issue, [])
    out.append(f"\n{'='*100}\n{label}   [{len(files)} files]")
    for rel, t in sorted(files):
        role = ""
        m = re.search(r'EVIDENCE ROLE:\s*([a-z_]+)', t, re.I) or re.search(r'Evidence role\s*\|\s*([a-z_]+)', t, re.I) or re.search(r'"evidence_role"\s*:\s*"([^"]+)"', t, re.I)
        if m: role = m.group(1)
        if not role:
            m = re.search(r'evidence[_ ]role[\"\']?\s*[:|=]\s*[\"\']?([a-z_]+)', t, re.I)
            if m: role = m.group(1)
        # native record / operative statement
        nat = (section(t, r'NATIVE RECORD\s*\n', [r'\n\s*\n', r'SOURCE LINEAGE', r'BUSINESS CONTEXT', r'RELIANCE', r'CHRONOLOGY', r'PROVENANCE'])
               or section(t, r'## Native record\s*\n', [r'## ', r'\n'])
               or section(t, r'"native_record"\s*:\s*"', [r'"'])
               or section(t, r'native record CB-DOC', [r'\.']))
        # any CB-MA-2401-X### statement
        ops = re.findall(r'([^.]{0,300}?CB-MA-2401-[A-Z]\d+[^.]{0,400}\.)', t)
        out.append(f"\n--- {rel}  (role={role or '?'})")
        if nat and len(nat) > 20:
            out.append(f"    NATIVE: {nat[:700]}")
        for o in ops[:2]:
            out.append(f"    OP: {' '.join(o.split())[:600]}")
        if not nat and not ops:
            # csv fallback: print header lines
            head = " ".join(t.split())[:400]
            out.append(f"    HEAD: {head}")

print("\n".join(out)[:20000])
